    if d is None and h is None and mi is None and sec is None:
        raise ValueError(f"malformed duration: {s!r}")
    if 'T' in s and h is None and mi is None and sec is None:
        raise ValueError(f"malformed duration: {s!r}")
    total = 0
    if d is not None:
        total += int(d) * 86400
    if h is not None:
        total += int(h) * 3600

