import re

def iso_duration_to_seconds(s: str) -> int:
    m = re.fullmatch(r'P(?:(\d+)D)?(?:T(?:(\d+)H)?(?:(\d+)M)?(?:(\d+)S)?)?', s)
    if not m:
        raise ValueError(f"malformed ISO-8601 duration: {s!r}")
    days, hours, minutes, seconds = (int(x) if x is not None else 0 for x in m.groups())
    if days == hours == minutes == seconds == 0:
        raise ValueError(f"malformed ISO-8601 duration: {s!r}")
    if 'T' in s and hours == minutes == seconds == 0:
        raise ValueError(f"malformed ISO-8601 duration: {s!r}")
    return days * 86400 + hours * 3600 + minutes * 60 + s

