import re

def iso_duration_to_seconds(s: str) -> int:
    pattern = r'^P(?:(\d+)D)?(?:T(?:(\d+)H)?(?:(\d+)M)?(?:(\d+)S)?)?$'
    match = re.fullmatch(pattern, s)

    if not match or s == 'P' or s.endswith('T'):
        raise ValueError("Malformed ISO-8601 duration")

    d, h, m, sec = match.groups()

    total = 0
    if d is not None:
        total += int(d) * 86400
    if h is not None:
        total += int(h) * 3600
    if m is not None:
        total += int(m) * 60
    if sec is not None:
        total += int(sec)

    return total
```

