def calc(items, tier):
    DISCOUNT_FACTORS = {
        "GOLD": 0.8,
        "SILVER": 0.9,
        "BRONZE": 0.95
    }
    subtotal = sum(unit_price * quantity for unit_price, quantity in items)
    discount_factor = DISCOUNT_FACTORS.get(tier, 1.0)
    total = subtotal * discount_factor
    total = max(total, 0)
    return round(total, 2)
